function unicas(permissoes: PermissaoSistema[]) {
  return Array.from(new Set(permissoes));
}

export function permissoesPadraoPorPerfil(role: string) {
  const perfil = String(role || "").toUpperCase();

  if (perfil === "ADMIN") {
    return [...TODAS_PERMISSOES];
  }

  if (perfil === "ATENDENTE") {
    return unicas([
      "dashboard.ver",
      ...PERMISSOES_OS_ATENDIMENTO,
      ...PERMISSOES_PRODUTOS_OPERACAO,
    ]);
  }

  if (perfil === "TECNICO") {
    return unicas([
      "dashboard.ver",
      ...PERMISSOES_OS_TECNICO,
      ...PERMISSOES_PRODUTOS_OPERACAO,
    ]);
  }

  if (perfil === "FINANCEIRO") {
    return unicas([
      "dashboard.ver",
      ...PERMISSOES_FINANCEIRO,
      ...PERMISSOES_PRODUTOS_OPERACAO,
    ]);
  }

  return unicas(["dashboard.ver", ...PERMISSOES_PRODUTOS_OPERACAO]);
}

export function normalizarPermissoes(valor: unknown, role: string) {
  const perfil = String(role || "").toUpperCase();

  if (perfil === "ADMIN") {
    return [...TODAS_PERMISSOES];
  }

  const permitidas = new Set<string>(TODAS_PERMISSOES);

  const base = Array.isArray(valor)
    ? valor.map((item) => String(item || "").trim())
    : permissoesPadraoPorPerfil(role);

  return Array.from(new Set(base.filter((item) => permitidas.has(item))));
}

// proxy.ts
import { NextRequest, NextResponse } from "next/server";

const COOKIE_NAME = "nio_os_session";
const AUTH_SECRET = process.env.AUTH_SECRET || "nio-os-dev-secret-change-this";
const SESSION_MAX_AGE_MS = 1000 * 60 * 60 * 24 * 30;

const ROTAS_PUBLICAS = ["/login", "/primeiro-acesso", "/sair"];

const APIS_PUBLICAS = [
  "/api/auth/setup",
  "/api/auth/login",
  "/api/auth/logout",
  "/api/auth/me",
];

function rotaEhPublica(pathname: string) {
  return ROTAS_PUBLICAS.some(
    (rota) => pathname === rota || pathname.startsWith(`${rota}/`)
  );
}

function apiEhPublica(pathname: string) {
  return APIS_PUBLICAS.some(
    (rota) => pathname === rota || pathname.startsWith(`${rota}/`)
  );
}

function base64Url(buffer: ArrayBuffer) {
  const bytes = new Uint8Array(buffer);
  let texto = "";

  for (let i = 0; i < bytes.length; i++) {
    texto += String.fromCharCode(bytes[i]);
  }

  return btoa(texto)
    .replace(/=/g, "")
    .replace(/\+/g, "-")
    .replace(/\//g, "_");
}

function decodificarBase64Url(valor: string) {
  const base64 = valor.replace(/-/g, "+").replace(/_/g, "/");
  const padding = "=".repeat((4 - (base64.length % 4)) % 4);

  return atob(base64 + padding);
}

async function assinar(valor: string) {
  const encoder = new TextEncoder();

  const chave = await crypto.subtle.importKey(
    "raw",
    encoder.encode(AUTH_SECRET),
    {
      name: "HMAC",
      hash: "SHA-256",
    },
    false,
    ["sign"]
  );

  const assinatura = await crypto.subtle.sign(
    "HMAC",
    chave,
    encoder.encode(valor)
  );

  return base64Url(assinatura);
}

async function tokenValido(token?: string) {
  if (!token) return false;

  const [payloadBase64, assinatura] = token.split(".");

  if (!payloadBase64 || !assinatura) return false;

  const assinaturaEsperada = await assinar(payloadBase64);

  if (assinatura !== assinaturaEsperada) return false;

  try {
    const payload = JSON.parse(decodificarBase64Url(payloadBase64));

    if (!payload?.userId) return false;

    const criadoEm = Number(payload.iat);

    if (!Number.isFinite(criadoEm)) return false;

    const agora = Date.now();

    if (criadoEm > agora + 1000 * 60 * 5) return false;
    if (agora - criadoEm > SESSION_MAX_AGE_MS) return false;

    return true;
  } catch {
    return false;
  }
}

function respostaSemCache(response: NextResponse) {
  response.headers.set("Cache-Control", "no-store");
  return response;
}

export async function proxy(request: NextRequest) {
  // Nio-OS Desktop: endpoint público usado pelo Electron e clientes da rede
  // para detectar se este computador é o servidor ativo.
  if (request.nextUrl.pathname === "/api/local/health") {
    return NextResponse.next();
  }

  const { pathname } = request.nextUrl;

  if (
    pathname.startsWith("/_next") ||
    pathname === "/favicon.ico"
  ) {
    return NextResponse.next();
  }

  if (pathname.startsWith("/uploads/anexos")) {
    return respostaSemCache(
      new NextResponse("Arquivo protegido.", {
        status: 404,
      })
    );
  }

  if (pathname.startsWith("/uploads")) {
    return NextResponse.next();
  }

  if (rotaEhPublica(pathname)) {
    return NextResponse.next();
  }

  if (pathname.startsWith("/api") && apiEhPublica(pathname)) {
    return respostaSemCache(NextResponse.next());
  }

  const token = request.cookies.get(COOKIE_NAME)?.value;
  const autenticado = await tokenValido(token);

  if (autenticado) {
    return respostaSemCache(NextResponse.next());
  }

  if (pathname.startsWith("/api")) {
    return respostaSemCache(
      NextResponse.json(
        {
          message: "Sessão expirada ou usuário não autenticado.",
        },
        { status: 401 }
      )
    );
  }

  const urlLogin = request.nextUrl.clone();
  urlLogin.pathname = "/login";
  urlLogin.searchParams.set("next", pathname);

  return respostaSemCache(NextResponse.redirect(urlLogin));
}

export const config = {
  matcher: ["/((?!.*\\..*).*)", "/uploads/anexos/:path*"],
};
